var UserConnection = Get<UserConnection>("UserConnection");
var dmsService = new DMSService(UserConnection);
var token = new Token(UserConnection);

string clientId = Get<string>("ClientId");
string clientSecret = Get<string>("ClientSecret");
string grantType = Get<string>("GrantType");

try {
	if (string.IsNullOrEmpty(clientId) || string.IsNullOrEmpty(clientSecret) || string.IsNullOrEmpty(grantType)) {
		Set("XRequestID", token.RandomRequestID());
		var result = dmsService.GetToken().GetAwaiter().GetResult();
		Set("Result", JsonConvert.SerializeObject(result, Formatting.Indented));
	} else {
		var param = token.GetParam(clientId, clientSecret, grantType);
		Set("XRequestID", token.RandomRequestID());
		Set("RequestBody", JsonConvert.SerializeObject(param, Formatting.Indented));
		var result = dmsService.GetToken(param).GetAwaiter().GetResult();
		Set("Result", JsonConvert.SerializeObject(result, Formatting.Indented));
	}
} catch (Exception e) {
	Set("Result", e.Message);
}

return true;
